INSERT INTO	dbo.CustStakeLevel_Member (CustID, SportType, BetType, StakeLevelList, LastUpdated)
SELECT	ml.CustID, cs.SportType, cs.BetType, ISNULL(sr.LowestStakeLevel, ''), GETDATE()
FROM	#MemberList ml 
		INNER JOIN dbo.CustStakeLevel_Agent AS cs WITH(NOLOCK) ON ml.recommend = cs.CustID
		OUTER APPLY (
					SELECT TOP(1) ISNULL(CONVERT(VARCHAR(20), sl.StakeLevelID), '') AS LowestStakeLevel
					FROM (
							SELECT	CAST(val AS INT) AS val
							FROM	dbo.strSplit(cs.StakeLevelList, ',')
						) AS ss
						INNER JOIN	dbo.StakeLevel AS sl WITH(NOLOCK) ON	ss.val = sl.StakeLevelID
					ORDER BY	sl.MaxStake, sl.MinStake, sl.GameGroupID
					) sr
WHERE	cs.SportType = 212 AND cs.BetType = 4001
